import { STSClient, AssumeRoleCommand } from '@aws-sdk/client-sts';
import { BadRequestException } from '@nestjs/common';

export interface AssumedRoleCredentials {
    accessKeyId: string;
    secretAccessKey: string;
    sessionToken: string;
}

/**
 * Attempt to assume the supplied IAM role using the supplied external id.
 *
 * This proves that MeteringCo is actually able to assume the customer's scraper
 * role before we persist it. If the role cannot be assumed (it does not exist,
 * the trust policy does not allow us, or the external id does not match) a
 * {@link BadRequestException} is thrown so that nothing else in the save is
 * written.
 */
export const assumeScraperRole = async (
    iamRoleArn: string,
    externalId?: string,
    region = 'us-east-1',
): Promise<AssumedRoleCredentials> => {
    const sts = new STSClient({ region });
    try {
        const { Credentials } = await sts.send(
            new AssumeRoleCommand({
                RoleArn: iamRoleArn,
                RoleSessionName: 'meteringco-scraper-validation',
                ExternalId: externalId ? externalId : undefined,
            }),
        );
        if (!Credentials) {
            throw new BadRequestException(
                'Unable to assume the provided IAM role with the supplied external ID',
            );
        }
        return {
            accessKeyId: Credentials.AccessKeyId,
            secretAccessKey: Credentials.SecretAccessKey,
            sessionToken: Credentials.SessionToken,
        };
    } catch (err) {
        if (err instanceof BadRequestException) {
            throw err;
        }
        throw new BadRequestException(
            'Unable to assume the provided IAM role with the supplied external ID',
        );
    }
};
