import { Test, TestingModule } from '@nestjs/testing';
import { SettingsService } from './settings.service.js';
import { createMock } from '@golevelup/ts-jest';
import { InfluxService } from '../influx/influx.service.js';
import { IAMClient, CreateRoleCommand, PutRolePolicyCommand } from '@aws-sdk/client-iam';
import { BadRequestException } from '@nestjs/common';

const iam = new IAMClient({});
const ACCT = '600000000042';
const TRUST = JSON.stringify({
    Version: '2012-10-17',
    Statement: [{ Effect: 'Allow', Principal: { AWS: '*' }, Action: 'sts:AssumeRole' }],
});

async function ensureRole(name: string, withEc2Read: boolean) {
    try {
        await iam.send(new CreateRoleCommand({ RoleName: name, AssumeRolePolicyDocument: TRUST }));
    } catch (e) {
        /* already exists */
    }
    if (withEc2Read) {
        await iam.send(
            new PutRolePolicyCommand({
                RoleName: name,
                PolicyName: 'ec2read',
                PolicyDocument: JSON.stringify({
                    Version: '2012-10-17',
                    Statement: [{ Effect: 'Allow', Action: ['ec2:Describe*'], Resource: '*' }],
                }),
            }),
        );
    }
    return `arn:aws:iam::${ACCT}:role/${name}`;
}

describe('cloudIAM scraper role validation (repro)', () => {
    let service: SettingsService;
    let influxService: InfluxService;
    const businessID = 'repro-business';
    const subject = 'repro-subject';

    let goodArn: string;
    let noPermArn: string;

    beforeAll(async () => {
        goodArn = await ensureRole('repro-scraper-good', true);
        noPermArn = await ensureRole('repro-scraper-noperm', false);
    });

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({ providers: [SettingsService] })
            .useMocker(createMock)
            .compile();
        service = module.get(SettingsService);
        influxService = module.get(InfluxService);
        jest.spyOn(influxService, 'getLatestSettings').mockResolvedValue([]);
    });

    afterEach(() => jest.clearAllMocks());

    it('saves a valid role that can be assumed and read inventory', async () => {
        const load = jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        const result = await service.update({
            businessID,
            subject,
            cloudIAM: { iamRoleArn: goodArn, externalId: 'ext-123' },
        } as any);
        expect(load).toBeCalledTimes(1);
        expect(result.data[0].cloudIAM).toEqual({ iamRoleArn: goodArn, externalId: 'ext-123' });
    });

    it('rejects (bad request) a role that cannot read inventory and writes nothing', async () => {
        const load = jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        await expect(
            service.update({ businessID, subject, cloudIAM: { iamRoleArn: noPermArn, externalId: 'ext' } } as any),
        ).rejects.toBeInstanceOf(BadRequestException);
        expect(load).not.toBeCalled();
    });

    it('rejects (bad request) a role that cannot be assumed and writes nothing', async () => {
        const load = jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        await expect(
            service.update({
                businessID,
                subject,
                cloudIAM: { iamRoleArn: `arn:aws:iam::${ACCT}:role/does-not-exist-xyz`, externalId: 'ext' },
            } as any),
        ).rejects.toBeInstanceOf(BadRequestException);
        expect(load).not.toBeCalled();
    });

    it('blank role disconnects and clears the external id', async () => {
        const load = jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        const result = await service.update({
            businessID,
            subject,
            cloudIAM: { iamRoleArn: '', externalId: 'stale-ext' },
        } as any);
        expect(load).toBeCalledTimes(1);
        expect(result.data[0].cloudIAM).toEqual({ iamRoleArn: '' });
        expect((result.data[0].cloudIAM as any).externalId).toBeUndefined();
    });

    it('a cloudIAM block naming no role is invalid, not a disconnect', async () => {
        const load = jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        await expect(
            service.update({ businessID, subject, cloudIAM: { externalId: 'ext-only' } } as any),
        ).rejects.toBeInstanceOf(BadRequestException);
        expect(load).not.toBeCalled();
    });

    it('leaves updates without cloudIAM untouched', async () => {
        const load = jest.spyOn(influxService, 'loadPoints').mockResolvedValue();
        const result = await service.update({ businessID, subject, businessName: 'Acme' } as any);
        expect(load).toBeCalledTimes(1);
        expect(result.message).toEqual('Setting updated successfully');
    });
});
